#include <iostream>
#include <cstdlib>
using namespace std;

int n, s[100];

bool muqara(int x) {
    for (int i = 1; i < x; ++i)
        if (s[i] == s[x] || abs(i - x) == abs(s[i] - s[x]))
            return true;
    return false;
}

void dfs(int k) {
    if (k > n) {
        for (int i = 1; i <= n; ++i)
            cout << s[i] << " ";
        cout << '\n';
        return;
    }

    for (s[k] = 1; s[k] <= n; ++s[k])
        if (!muqara(k))
            dfs(k + 1);

    s[k] = 0;
}

int main() {
    cin >> n;
    n = 8;
    dfs(1);
    return 0;
}

#include <iostream>
#include <vector>
#include <cstdlib>

using namespace std;

int n;
vector<int> position;

bool conflict(int column) {
    for (int i = 1; i < column; ++i) {
        if (position[i] == position[column] ||
            abs(i - column) == abs(position[i] - position[column])) {
            return true;
        }
    }
    return false;
}

void dfs(int column) {
    if (column > n) {
        for (int i = 1; i <= n; ++i) {
            cout << position[i] << ' ';
        }
        cout << '\n';
        return;
    }

    for (position[column] = 1; position[column] <= n; ++position[column]) {
        if (!conflict(column)) {
            dfs(column + 1);
        }
    }
    position[column] = 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n) || n < 1) {
        return 0;
    }

    position.assign(n + 1, 0);
    dfs(1);
    return 0;
}

